def choose_move(observation):
    w = observation["grid_width"]
    h = observation["grid_height"]
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]
    resources = observation["resources"]
    obstacles = set((x, y) for x, y in observation["obstacles"])
    if not resources:
        return [0, 0]

    def cheb(a, b, c, d):
        dx = abs(a - c)
        dy = abs(b - d)
        return dx if dx > dy else dy

    best = None
    best_val = None
    for rx, ry in resources:
        sd = cheb(sx, sy, rx, ry)
        od = cheb(ox, oy, rx, ry)
        val = sd - 0.15 * od  # prefer resources we can reach sooner
        if best is None or val < best_val or (val == best_val and (sd < best[0] or (sd == best[0] and od < best[1]))):
            best = (sd, od, rx, ry)
            best_val = val
    _, _, tx, ty = best

    moves = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            nx, ny = sx + dx, sy + dy
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles:
                moves.append((dx, dy))

    def dist_after(dx, dy):
        nx, ny = sx + dx, sy + dy
        return cheb(nx, ny, tx, ty)

    def opp_dist_after(dx, dy):
        nx, ny = sx + dx, sy + dy
        return cheb(nx, ny, ox, oy)

    # Prefer getting closer to target; then avoid being closer to opponent.
    best_move = None
    best_key = None
    for dx, dy in moves:
        d = dist_after(dx, dy)
        od = opp_dist_after(dx, dy)
        key = (d, -od, dx, dy)
        if best_key is None or key < best_key:
            best_key = key
            best_move = (dx, dy)

    return [int(best_move[0]), int(best_move[1])]

def choose_move(observation):
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]
    w, h = observation["grid_width"], observation["grid_height"]
    resources = observation.get("resources") or []
    obstacles = observation.get("obstacles") or []
    blocked = {(p[0], p[1]) for p in obstacles}

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in blocked

    def man(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    dirs = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]
    if not resources:
        best = None
        bestm = [0, 0]
        for dx, dy in dirs:
            nx, ny = sx + dx, sy + dy
            if not inb(nx, ny):
                continue
            val = man(nx, ny, ox, oy)
            if best is None or val < best or (val == best and (nx, ny) < (sx + bestm[0], sy + bestm[1])):
                best = val
                bestm = [dx, dy]
        return bestm

    best_score = None
    best_move = [0, 0]
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny):
            continue

        local_best = None
        for rx, ry in resources:
            ds = man(nx, ny, rx, ry)
            do = man(ox, oy, rx, ry)

            # Advantage-first, then speed. Strongly avoid ceding resources.
            # Scores are deterministic integers.
            adv = do - ds  # positive means we are closer
            score = 6 * adv - 2 * ds + (2 if ds == 0 else 0) - (3 if adv < 0 and do <= ds + 1 else 0)

            # Prefer resources opponent can reach soon less than ours (force earlier grabs/intercepts).
            if do < ds:
                score += 2

            if local_best is None or score > local_best:
                local_best = score

        if best_score is None or local_best > best_score or (local_best == best_score and (nx, ny) < (sx + best_move[0], sy + best_move[1])):
            best_score = local_best
            best_move = [dx, dy]

    return best_move

def choose_move(observation):
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]
    w, h = observation["grid_width"], observation["grid_height"]
    resources = observation.get("resources") or []
    obstacles = observation.get("obstacles") or []
    blocked = {(p[0], p[1]) for p in obstacles}

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in blocked

    def man(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    dirs = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]
    safe_moves = []
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if inb(nx, ny):
            safe_moves.append((dx, dy, nx, ny))
    if not safe_moves:
        return [0, 0]

    if not resources:
        # Hold position unless it improves distance to opponent (avoid stepping into dead zones)
        best = None
        for dx, dy, nx, ny in safe_moves:
            d = man(nx, ny, ox, oy)
            if best is None or d < best[0] or (d == best[0] and (dx, dy) < (best[1], best[2])):
                best = (d, dx, dy)
        return [best[1], best[2]]

    # Pick target with largest "lead" (we arrive earlier), tie-break by nearer + resource "density" (closer to other resources).
    best_t = None
    for rx, ry in resources:
        myt = man(sx, sy, rx, ry)
        ot = man(ox, oy, rx, ry)
        lead = ot - myt  # positive means we reach first
        density = 0
        for r2x, r2y in resources:
            if (r2x, r2y) != (rx, ry) and man(rx, ry, r2x, r2y) <= 2:
                density += 1
        key = (lead, -myt, density, -((rx + ry) % 2), -rx, -ry)
        if best_t is None or key > best_t[0]:
            best_t = (key, (rx, ry), myt, ot)
    (rx, ry) = best_t[1]

    # Move one step to reduce distance to chosen target; if opponent threatens closer resource, switch.
    def threat_score():
        best = None
        for tx, ty in resources:
            myt = man(sx, sy, tx, ty)
            ot = man(ox, oy, tx, ty)
            lead = ot - myt
            key = (lead, -myt)
            if best is None or key > best[0]:
                best = (key, (tx, ty))
        return best

    # Look-ahead: if we can't keep lead at next step, choose alternative target that we can.
    best_move = None
    for dx, dy, nx, ny in safe_moves:
        my_next = man(nx, ny, rx, ry)
        ot_now = man(ox, oy, rx, ry)
        lead_next = ot_now - my_next
        # Evaluate if there exists a better target we can secure next.
        best_secure_key = None
        for tx, ty in resources:
            myt = man(nx, ny, tx, ty)
            ot = man(ox, oy, tx, ty)
            lead = ot - myt
            key = (lead, -myt, -((tx + ty) % 2), -tx, -ty)
            if best_secure_key is None or key > best_secure_key:
                best_secure_key = key
        # Primary: keep/extend lead; Secondary: get closer to target; Tertiary: avoid unnecessary movement.
        key = (lead_next, best_secure_key[0], -my_next, -((nx + ny) % 2), abs(dx) + abs(dy))
        if best_move is None or key > best_move[0]:
            best_move = (key, dx, dy)

    return [int(best_move[1]), int(best_move[2])]

